export const glossary: Record<string,string> = {
  'TDM':'TEMENOS Data Migration Services — tim layanan migrasi data Temenos.',
  'ETL':'Extract, Transform, Load — proses ekstraksi, transformasi, dan pemuatan data.',
  'DM':'Data Migration.',
  'R':'Responsible — pihak yang bertanggung jawab mengerjakan.',
  'P':'Participate — pihak yang berpartisipasi.',
  'S':'Sign-off — pihak yang memberikan persetujuan.',
  'E&S':'Engagement and Solution.',
  'SOW':'Statement of Work.',
  'DMS':'Data Mapping Sheet — lembar pemetaan data T24 Rnn.',
  'DES':'Data Extract Specification — spesifikasi ekstraksi data untuk rekonsiliasi dari T24.',
  'MCS':'Sample Migration and Cutover Approach (dokumen MS Word).',
  'MCM':'Migration Control Matrix (buku MS Excel).',
  'MCR':'Migration and Cutover Run Book (MS Project Plan).',
  'Rnn':'Tabel data T24 Rnn (mis. CUSTOMER, ACCOUNT).',
  'CoB':'Close Of Business — penutupan hari bisnis; first Migration CoB memutar tanggal ke hari bisnis berikutnya (go-live).',
  'TCCP':'Sertifikasi teknis T24 Core + Data Migration yang wajib dicapai partner.',
  'DMT':'Data Mapping Tables — pemetaan data per aplikasi T24 berdasarkan dependensi antar aplikasi.',
  'MPA':'Migration Project Agreement — agreement 3 bagian (perencanaan; work plan & schedule; approach & metode rekonsiliasi).',
  'Staging DB':'Staging Database — database kerja untuk konsolidasi, pengecekan, dan pembuatan file OFS sebelum upload ke T24.',
  'OFS':'Open Financial Service — format file upload ke T24; hasil akhir Staging Database berupa satu file OFS unik yang bersih dan benar.',
  'Dry Run':'Uji coba migrasi lengkap (Environment Preparation → Execution → Analysis & Anomalies) sebelum Go-Live Weekend.',
  'Enrichment':'Penambahan informasi pada data agar memenuhi field mandatory T24 saat take-on.',
  'Back-value':'Kemampuan mencatat accounting entry dengan tanggal masa lalu; alasan bisnis membutuhkan historical data.',
  'DMD':'DM.MAPPING.DEFINITION — record definisi mapping: format file incoming (delimiter/posisi), target aplikasi T24, load type, dan ID generation.',
  'DSC':'DM.SERVICE.CONTROL — work-file yang mengontrol eksekusi load (company, file, thread, run status, log error).',
  'DSS':'DM.SERVICE.SCHEDULER — penjadwal & otomasi service validate → load → authorize.',
  'DMV':'Direktori output DATA.MAPPING.VERIFICATION (status PASS/FAIL verifikasi mapping).',
  'DM Tool':'T24 Data Migration Tool (GPAC) — alat load/validasi/ekstraksi/rekonsiliasi data untuk migrasi ke T24; dioperasikan via menu MB.DMMAIN.',
  'TSM/TSA':'Temenos Service Manager / Agent — infrastruktur service multi-thread tempat DM Tool berjalan (menggantikan EB.PHANTOM).',
  'STP':'Straight Through Processing — mode message-based via JMS queue (DM.LOAD.TYPE=ONLINE) sebagai alternatif file-based.',
  'DATA.MIG.COUNT':'Live file berisi jumlah record per aplikasi sebelum/sesudah migrasi (dipakai DM.INFORMATION).',
  'jBASE':'Database/environment runtime T24; fungsi WRITE jBASE adalah alternatif load selain OFS.',
  'DM.APP.BACKUP':'Aplikasi backup DM Tool — @ID APP.<PGM.FILE>; record aplikasi dipindah ke folder DM.BACKUP via service TSA (DOB-<id>).',
  'TSM':'Temenos Service Manager — mengelola TSA.SERVICE; untuk backup/load, TSM distart dan diotorisasi lewat TSA.SERVICE TSM (classic mode).',
  'TO TEMENOS':'Composite screen DM Tool (v1.1) untuk kerja efisien: memuat layar DMD, DSC, dsb. dalam satu tampilan.',
};

